sp_widget.client_script:
api.controller=function($scope) {

    var c = this;


    // Default section
    c.activeSection = 'dashboard';


    // Sidebar navigation
    c.selectSection = function(section) {

        c.activeSection = section;

    };


    // Submit feedback
    c.submitFeedback = function(feedback) {


        // Check required fields
        if (!feedback.overall_rating ||
            !feedback.resolution_satisfaction ||
            !feedback.feedback_comments) {

            alert("Please fill all feedback fields.");

            return;
        }


        // Send data to Server Script
        c.server.get({

            action: "saveFeedback",

            sys_id: feedback.sys_id,

            overall_rating:
                feedback.overall_rating,

            resolution_satisfaction:
                feedback.resolution_satisfaction,

            feedback_comments:
                feedback.feedback_comments

        }).then(function(response) {


            if (response.data.success) {

                // Refresh the feedback records
                c.data.feedbacks =
                    response.data.feedbacks;

                alert(
                    "Feedback submitted successfully!"
                );

            } else {

                alert(
                    response.data.message ||
                    "Unable to submit feedback."
                );

            }

        });

    };

}

sp_widget.css:
.student-dashboard {
  min-height: 100vh;
  background: #f5f7fb;
  font-family: Arial, sans-serif;
}


/* Header */

.top-header {
  height: 70px;
  background: white;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 30px;
  border-bottom: 1px solid #e5e7eb;
}

.brand {
  font-size: 22px;
  font-weight: bold;
}

.student-info {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 600;
}

.role-badge {
  background: #e8f0ff;
  color: #2563eb;
  padding: 5px 10px;
  border-radius: 20px;
  font-size: 12px;
}


/* Body */

.dashboard-body {
  display: flex;
  min-height: calc(100vh - 70px);
}


/* Sidebar */

.sidebar {
  width: 240px;
  background: white;
  border-right: 1px solid #e5e7eb;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.sidebar-menu {
  padding: 20px 15px;
}

.menu-item {
  padding: 13px 15px;
  margin-bottom: 8px;
  border-radius: 8px;
  cursor: pointer;
}

.menu-item:hover {
  background: #f1f5f9;
}

.menu-item.active {
  background: #e8f0ff;
  color: #2563eb;
  font-weight: 600;
}


/* Bottom user section */

.sidebar-bottom {
  padding: 20px;
  border-top: 1px solid #e5e7eb;
}

.user-name {
  font-weight: 600;
}

.user-role {
  font-size: 13px;
  color: #6b7280;
  margin-top: 4px;
}

.logout-btn {
  width: 100%;
  margin-top: 15px;
  padding: 9px;
  border: 1px solid #ddd;
  background: white;
  border-radius: 7px;
  cursor: pointer;
}


/* Main Content */

.main-content {
  flex: 1;
  padding: 35px;
}

.main-content h1 {
  margin-top: 0;
  font-size: 28px;
}

.welcome-text {
  color: #6b7280;
}
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 30px;
}

.kpi-card {
  background: white;
  padding: 22px;
  border-radius: 12px;
  border: 1px solid #e5e7eb;
}

.kpi-icon {
  font-size: 24px;
}

.kpi-number {
  font-size: 30px;
  font-weight: bold;
  margin-top: 10px;
}

.kpi-title {
  color: #6b7280;
  margin-top: 5px;
  font-size: 14px;
}
.requests-section {
  background: white;
  margin-top: 30px;
  padding: 25px;
  border-radius: 12px;
  border: 1px solid #e5e7eb;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.section-header h2 {
  margin: 0;
  font-size: 20px;
}

.section-header p {
  margin-top: 5px;
  color: #6b7280;
  font-size: 14px;
}

.view-all-btn {
  padding: 9px 16px;
  border: 1px solid #d1d5db;
  background: white;
  border-radius: 7px;
  cursor: pointer;
}

.requests-table-container {
  overflow-x: auto;
}

.requests-table {
  width: 100%;
  border-collapse: collapse;
}

.requests-table th {
  text-align: left;
  padding: 14px;
  background: #f8fafc;
  color: #6b7280;
  font-size: 13px;
}

.requests-table td {
  padding: 15px 14px;
  border-top: 1px solid #e5e7eb;
  font-size: 14px;
}

.priority,
.status {
  padding: 5px 10px;
  border-radius: 15px;
  font-size: 12px;
  font-weight: 600;
}

.priority.high {
  background: #fee2e2;
  color: #b91c1c;
}

.priority.medium {
  background: #fef3c7;
  color: #92400e;
}

.status.resolved {
  background: #dcfce7;
  color: #166534;
}

.status.new {
  background: #dbeafe;
  color: #1d4ed8;
}

sp_widget.script:
(function() {

    data.feedbacks = [];

    data.success = false;

    data.message = "";


    /*
     * ==========================================
     * SAVE EXISTING FEEDBACK
     * ==========================================
     */

    if (input && input.action == "saveFeedback") {


        var feedbackGR = new GlideRecord(
            'x_snc_campus_foo_1_food_complaint_feedbacks'
        );


        /*
         * Find the existing feedback record
         * using its sys_id
         */

        if (feedbackGR.get(input.sys_id)) {


            /*
             * SECURITY CHECK
             *
             * Make sure the feedback belongs
             * to the currently logged-in student.
             */

            if (
                feedbackGR.getValue('student')
                ==
                gs.getUserID()
            ) {


                /*
                 * Update ONLY these 3 fields
                 */

                feedbackGR.setValue(
                    'overall_rating',
                    input.overall_rating
                );


                feedbackGR.setValue(
                    'resolution_satisfaction',
                    input.resolution_satisfaction
                );


                feedbackGR.setValue(
                    'feedback_comments',
                    input.feedback_comments
                );


                /*
                 * Save existing record
                 */

                feedbackGR.update();


                data.success = true;

                data.message =
                    "Feedback submitted successfully.";


            } else {


                data.success = false;

                data.message =
                    "You cannot update this feedback.";

            }


        } else {


            data.success = false;

            data.message =
                "Feedback record not found.";

        }

    }


    /*
     * ==========================================
     * LOAD FEEDBACK RECORDS
     * ==========================================
     */

    var gr = new GlideRecord(
        'x_snc_campus_foo_1_food_complaint_feedbacks'
    );


    /*
     * Get only feedback records
     * belonging to logged-in student
     */

    gr.addQuery(
        'student',
        gs.getUserID()
    );


    gr.orderByDesc('sys_created_on');

    gr.query();


    while (gr.next()) {


        data.feedbacks.push({

            /*
             * Unique record ID
             */
            sys_id:
                gr.getUniqueValue(),


            /*
             * Feedback Number
             */
            number:
                gr.getValue('number'),


            /*
             * Existing request information
             */
            food_complaint:
                gr.getDisplayValue(
                    'food_complaint'
                ),


            use_case:
                gr.getDisplayValue(
                    'use_case'
                ),


            mess_hall:
                gr.getDisplayValue(
                    'mess_hall'
                ),


            meal_type:
                gr.getDisplayValue(
                    'meal_type'
                ),


            problem_type:
                gr.getValue(
                    'problem_type'
                ),


            /*
             * Student feedback fields
             */
            overall_rating:
                gr.getValue(
                    'overall_rating'
                ),


            resolution_satisfaction:
                gr.getValue(
                    'resolution_satisfaction'
                ),


            feedback_comments:
                gr.getValue(
                    'feedback_comments'
                )

        });

    }

})();
